INSERT INTO contest.market_dataset_asset (dataset_id, asset_id)
SELECT dataset.dataset_id, asset.asset_id
FROM contest.market_dataset AS dataset
JOIN reference.asset AS asset
    ON asset.exchange = 'UPBIT'
    AND asset.exchange_market_code IN ('KRW-ADA', 'KRW-BTC', 'KRW-CVC', 'KRW-ETH', 'KRW-IOST', 'KRW-LSK', 'KRW-ONG', 'KRW-SC', 'KRW-XLM', 'KRW-XRP')
WHERE dataset.round_id = '0f5f4f2a-9c4e-4b7a-8a3f-1c0e5a7b2d10';

DO $$
BEGIN
    IF (
        SELECT count(*)
        FROM contest.market_dataset_asset AS dataset_asset
        JOIN contest.market_dataset AS dataset ON dataset.dataset_id = dataset_asset.dataset_id
        WHERE dataset.round_id = '0f5f4f2a-9c4e-4b7a-8a3f-1c0e5a7b2d10'
    ) <> 40 THEN
        RAISE EXCEPTION '대회 종목이 reference.asset 에 모두 있어야 한다: % 개 필요', 40;
    END IF;
END $$;

