-- 4시간봉과 일봉은 1시간봉을 집계해서 만든다 (ADR-0005).
INSERT INTO contest.market_candle (
    dataset_id, asset_id, interval_minutes, open_time,
    open_price, high_price, low_price, close_price, trade_volume, trade_amount
)
SELECT hourly.dataset_id,
       hourly.asset_id,
       240,
       to_timestamp(floor(extract(epoch FROM hourly.open_time) / 14400) * 14400),
       (array_agg(hourly.open_price ORDER BY hourly.open_time))[1],
       max(hourly.high_price),
       min(hourly.low_price),
       (array_agg(hourly.close_price ORDER BY hourly.open_time DESC))[1],
       sum(hourly.trade_volume),
       sum(hourly.trade_amount)
FROM contest.market_candle AS hourly
JOIN contest.market_dataset AS dataset ON dataset.dataset_id = hourly.dataset_id
WHERE dataset.round_id = '0f5f4f2a-9c4e-4b7a-8a3f-1c0e5a7b2d10'
  AND hourly.interval_minutes = 60
GROUP BY hourly.dataset_id,
         hourly.asset_id,
         to_timestamp(floor(extract(epoch FROM hourly.open_time) / 14400) * 14400);

INSERT INTO contest.market_candle (
    dataset_id, asset_id, interval_minutes, open_time,
    open_price, high_price, low_price, close_price, trade_volume, trade_amount
)
SELECT hourly.dataset_id,
       hourly.asset_id,
       1440,
       to_timestamp(floor(extract(epoch FROM hourly.open_time) / 86400) * 86400),
       (array_agg(hourly.open_price ORDER BY hourly.open_time))[1],
       max(hourly.high_price),
       min(hourly.low_price),
       (array_agg(hourly.close_price ORDER BY hourly.open_time DESC))[1],
       sum(hourly.trade_volume),
       sum(hourly.trade_amount)
FROM contest.market_candle AS hourly
JOIN contest.market_dataset AS dataset ON dataset.dataset_id = hourly.dataset_id
WHERE dataset.round_id = '0f5f4f2a-9c4e-4b7a-8a3f-1c0e5a7b2d10'
  AND hourly.interval_minutes = 60
GROUP BY hourly.dataset_id,
         hourly.asset_id,
         to_timestamp(floor(extract(epoch FROM hourly.open_time) / 86400) * 86400);
